        auto draw=[&](){SceneLighting lighting;lighting.declared=true;check(render.set_scene_lighting(lighting),"prior lighting");render.begin_frame({});render.reset_arena();check(scene.draw(owner,render,&error)&&render.end_frame()&&render.scene_lighting()&&scene_lighting_equal(*render.scene_lighting(),lighting),"source passes and caller lighting restored");};
